<template>
  <main class="paper-studio">
    <aside class="paper-sidebar">
      <button class="brand" @click="router.push('/dashboard')"><span>D</span><b>Doki<small>机械设计</small></b></button>
      <div class="mode-switch"><button class="selected">论文设计</button><button @click="$emit('back')">结构方案</button></div>
      <p class="sidebar-label">论文章节</p>
      <a v-for="(chapter, i) in chapters" :key="chapter" :href="`#paper-chapter-${i+1}`"><span>{{ i+1 }}</span>{{ chapter }}</a>
      <section v-if="history.length" class="history"><p class="sidebar-label">最近任务</p><button v-for="item in history" :key="item.id" :class="{selected: job?.id===item.id}" @click="restore(item.id)">{{ item.title }}<small>{{ stateLabel(item.status) }}</small></button></section>
      <footer>题目驱动 · 图文完整交付</footer>
    </aside>
    <section class="paper-main">
      <header class="page-header"><div><span>机械设计 / 论文设计</span><h1>机械设计论文</h1><p>输入题目，Doki 自动规划正文与配图，生成完整 Word 稿件。</p></div><button class="secondary" @click="router.push('/dashboard')">返回工作台</button></header>
      <section class="input-panel">
        <label for="paper-title">论文题目</label>
        <div class="title-input"><input id="paper-title" v-model="title" maxlength="120" placeholder="例如：板类零件钻孔夹具结构设计" :disabled="busy || running" @keyup.enter="start"><button class="primary" :disabled="busy || running || !title.trim() || !readiness.ready" @click="start">{{ busy ? '正在创建…' : running ? '正在生成' : '立即生成' }}</button></div>
        <p>无需编辑大纲。约 8000 字，包含实物图、结构图、计算公式、至少 4 张零件图及 4 张云图。</p>
        <p v-if="!readiness.ready" class="notice">{{ readiness.message || '正在检查 Doki 生成服务…' }}</p>
        <small v-else>生成完成后按现有文档生成标准扣除 {{ readiness.costPoints }} 积分，失败不扣费。</small>
      </section>
      <p v-if="networkError" class="notice">{{ networkError }} <button class="text-button" @click="resumePolling">重新连接</button></p>
      <template v-if="job">
        <section class="progress-panel" aria-live="polite">
          <div class="progress-header"><div><span>DOKI 正在处理</span><h2>{{ job.stage }}</h2><p>{{ job.title }}</p></div><b>{{ job.progress }}%</b></div>
          <div class="progress-track" :class="{running}"><i :style="{width: `${job.progress}%`}"/><span v-if="running"/></div>
          <div class="progress-meta"><span>{{ completed }}/{{ job.tasks?.length || 31 }} 项已完成</span><span v-if="running">已等待 {{ elapsed }} · {{ runningTasks.length }} 项处理中</span><span v-else>{{ stateLabel(job.status) }}{{ job.wordCount ? ` · 正文 ${job.wordCount} 字` : '' }}</span></div>
          <p v-if="running" class="live-status">{{ runningTasks.slice(0,3).map(task=>task.label).join(' · ') || '任务已排队，Doki 正在准备生成' }}<span class="waiting-dots">…</span></p>
          <p v-if="job.error" class="notice">{{ job.error }}</p>
          <div class="actions"><button v-if="['FAILED','INTERRUPTED'].includes(job.status)" class="primary" :disabled="busy || !readiness.ready" @click="retry">继续生成</button><button v-if="job.status==='SUCCESS'" class="primary" :disabled="downloading" @click="download">{{ downloading ? '正在下载…' : '下载 Word 论文' }}</button><button v-if="!running" class="secondary" @click="newPaper">生成另一篇</button></div>
        </section>
        <section class="chapter-progress"><h2>章节生成进度</h2><article v-for="(chapter, i) in chapters" :id="`paper-chapter-${i+1}`" :key="chapter" class="chapter-card"><header><div><span class="chapter-icon">{{ chapterDone(i+1) ? '✓' : i+1 }}</span><div><h3>第 {{ i+1 }} 章 · {{ chapter }}</h3><small>{{ chapterTasks(i+1).filter(t=>t.status==='completed').length }}/{{ chapterTasks(i+1).length }} 小节完成 · {{ chapterFigures(i+1).filter(f=>f.status==='completed').length }}/{{ chapterFigures(i+1).length }} 配图完成</small></div></div><span>{{ chapterDone(i+1) ? '已完成' : running ? '处理中' : '待完成' }}</span></header><div class="section-tags"><span v-for="task in chapterTasks(i+1)" :key="task.id" :class="task.status">{{ task.label }} <b>{{ task.status==='completed' ? '✓' : task.status==='running' ? '生成中' : task.status==='failed' ? '需重试' : '等待' }}</b></span></div><div v-if="chapterFigures(i+1).length" class="figure-tags"><span v-for="figure in chapterFigures(i+1)" :key="figure.id">图 {{ figure.id }} · {{ figure.caption }} {{ figure.status==='completed' ? '✓' : '' }}</span></div></article></section>
        <section v-if="job.status==='SUCCESS' && previews.length" class="preview-panel"><h2>配图预览</h2><p>云图用于定性结构分析，数值计算采用正文解析公式。</p><div class="preview-grid"><figure v-for="preview in previews" :key="preview.id"><img :src="preview.url" :alt="preview.caption" loading="lazy"><figcaption>图 {{ preview.id }} · {{ preview.caption }}</figcaption></figure></div></section>
      </template>
      <section v-else class="empty-plan"><h2>按这套结构自动完成</h2><div><article v-for="(chapter, i) in chapters" :id="`paper-chapter-${i+1}`" :key="chapter"><small>第 {{ i+1 }} 章</small><h3>{{ chapter }}</h3><p>{{ descriptions[i] }}</p></article></div></section>
    </section>
  </main>
</template>

<script setup>
import {computed, onMounted, onBeforeUnmount, ref} from 'vue'
import {useRoute, useRouter} from 'vue-router'
import {getAuthItem} from '../utils/authStorage'
import {mechanicalPaperReadiness, createMechanicalPaper, listMechanicalPapers, getMechanicalPaper, retryMechanicalPaper, downloadMechanicalPaper, getMechanicalPaperImage} from '../api/rewrite'
defineEmits(['back'])
const router=useRouter(), title=ref(''), job=ref(null), history=ref([]), busy=ref(false), downloading=ref(false), readiness=ref({ready:false}), networkError=ref(''), previews=ref([]), now=ref(Date.now())
const route=useRoute()
const chapters=['绪论','总体方案与结构设计','主要参数与设计计算','主要零件设计','装配表达与结构分析','总结与展望']
const descriptions=['背景与设计目标，1 张实物图','统一设计参数、结构图与总装结构','载荷、公式、强度与精度计算','至少 4 张不同零件图','三维总装、二维总装、网格图及 4 张云图','总结设计结果与改进方向']
const storageKey=`doki-mechanical-paper:${getAuthItem('dropai_username')}`
let pollTimer, clockTimer, stopped=false, selection=0
const running=computed(()=>job.value?.status==='RUNNING'), completed=computed(()=>job.value?.tasks?.filter(t=>t.status==='completed').length || 0), runningTasks=computed(()=>job.value?.tasks?.filter(t=>t.status==='running') || [])
const elapsed=computed(()=>{const seconds=Math.max(0,Math.floor((now.value-(job.value?.startedAt || now.value))/1000));return `${Math.floor(seconds/60)} 分 ${seconds%60} 秒`})
function chapterTasks(chapter){return job.value?.tasks?.filter(t=>t.id.startsWith(`text:${chapter}.`)) || []}
function chapterFigures(chapter){return job.value?.figures?.filter(f=>f.section.startsWith(`${chapter}.`)) || []}
function chapterDone(chapter){const tasks=[...chapterTasks(chapter),...chapterFigures(chapter)];return tasks.length>0 && tasks.every(t=>t.status==='completed')}
function stateLabel(status){return {RUNNING:'正在生成',SUCCESS:'生成完成',FAILED:'生成未完成',INTERRUPTED:'可继续生成'}[status] || status}
function remember(id){try {localStorage.setItem(storageKey,id)} catch {}}
function forget(){try {localStorage.removeItem(storageKey)} catch {}}
function clearPreviews(){previews.value.forEach(p=>URL.revokeObjectURL(p.url));previews.value=[]}
function apply(state){job.value=state;title.value=state.title;remember(state.id)}
async function start(){if(busy.value || running.value || !title.value.trim() || !readiness.value.ready)return;busy.value=true;try{clearPreviews();apply(await createMechanicalPaper(title.value.trim()));selection++;poll(selection);await refreshHistory()}catch { /* Shared API handler shows the error. */ }finally{busy.value=false}}
async function refreshHistory(){history.value=await listMechanicalPapers()}
async function restore(id){const version=++selection;clearTimeout(pollTimer);clearPreviews();busy.value=true;try{const state=await getMechanicalPaper(id);if(version!==selection || stopped)return;apply(state);networkError.value='';if(running.value)poll(version);else if(state.status==='SUCCESS')loadPreviews(version)}catch {networkError.value='任务读取失败，任务仍保存在服务端。'}finally{busy.value=false}}
async function poll(version){clearTimeout(pollTimer);if(stopped || version!==selection || !job.value)return;try{const state=await getMechanicalPaper(job.value.id);if(stopped || version!==selection)return;apply(state);networkError.value='';if(state.status==='RUNNING')pollTimer=setTimeout(()=>poll(version),2000);else{await refreshHistory();if(state.status==='SUCCESS')loadPreviews(version)}}catch {if(!stopped && version===selection){networkError.value='暂时无法读取进度，正在自动重连；请勿重复创建任务。';pollTimer=setTimeout(()=>poll(version),6000)}}}
async function resumePolling(){try{readiness.value=await mechanicalPaperReadiness();if(job.value)poll(selection);else{await refreshHistory();let id;try{id=localStorage.getItem(storageKey)}catch{}const previous=history.value.find(j=>j.id===id) || history.value.find(j=>j.status==='RUNNING' || j.status==='INTERRUPTED');if(previous)await restore(previous.id);else networkError.value=''}}catch{networkError.value='Doki 服务暂时不可用，任务仍保存在服务端。'}}
async function retry(){if(busy.value)return;busy.value=true;try{apply(await retryMechanicalPaper(job.value.id));poll(++selection)}catch {}finally{busy.value=false}}
async function download(){downloading.value=true;try{const blob=await downloadMechanicalPaper(job.value.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${job.value.title}.docx`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch {}finally{downloading.value=false}}
function newPaper(){selection++;clearTimeout(pollTimer);clearPreviews();job.value=null;title.value='';networkError.value='';forget()}
async function loadPreviews(version){const id=job.value.id;clearPreviews();for(const figure of job.value.figures || []){try{const blob=await getMechanicalPaperImage(id,figure.id);if(stopped || selection!==version)return;previews.value.push({...figure,url:URL.createObjectURL(blob)})}catch { /* A preview failure does not hide the Word download. */ }}}
onMounted(async()=>{clockTimer=setInterval(()=>now.value=Date.now(),1000);try{readiness.value=await mechanicalPaperReadiness();await refreshHistory();let remembered;try{remembered=localStorage.getItem(storageKey)}catch {}const match=history.value.find(j=>j.id===remembered) || history.value.find(j=>j.status==='RUNNING' || j.status==='INTERRUPTED');if(route.query.paperId)await restore(String(route.query.paperId));else if(match)await restore(match.id)}catch {networkError.value='Doki 服务暂时不可用，请确认服务已启动。'}})
onBeforeUnmount(()=>{stopped=true;selection++;clearTimeout(pollTimer);clearInterval(clockTimer);clearPreviews()})
</script>

<style scoped>
