anel label{font-size:14px;font-weight:700}.title-input{display:flex;gap:12px;margin-top:14px}.title-input input{flex:1;min-width:0;padding:15px 18px;border:1px solid #dedfec;border-radius:10px;font-size:16px;outline:none}.title-input input:focus{border-color:#7764e6}.primary{border:0;border-radius:10px;padding:13px 23px;color:white;background:linear-gradient(120deg,#7159ea,#9561eb);font-weight:700;cursor:pointer}.primary:disabled{opacity:.55;cursor:default}.input-panel small{font-size:11px;color:#a0a3b4}.notice{color:#b87935!important;font-size:13px}.text-button{border:0;background:none;color:#715ee1;cursor:pointer}.progress-header,.progress-meta{display:flex;justify-content:space-between;align-items:center}.progress-header span{font-size:10px;letter-spacing:.1em;color:#7963e5}.progress-header h2{font-size:22px;margin:9px 0}.progress-header p{color:#9599aa;font-size:12px}.progress-header>b{font-size:28px;color:#7861df}.progress-track{position:relative;height:8px;overflow:hidden;background:#efedf8;border-radius:9px;margin:20px 0 12px}.progress-track i{display:block;height:100%;background:linear-gradient(90deg,#735cf0,#dc5abe);transition:width .7s ease;border-radius:9px}.progress-track.running>span{position:absolute;inset:0;width:25%;background:linear-gradient(90deg,transparent,#c5b9ff9c,transparent);animation:travel 2s linear infinite}.progress-meta{font-size:12px;color:#9297aa}.live-status{font-size:12px;color:#80798f;line-height:1.8}.waiting-dots{animation:pulse 1.4s infinite}.actions{display:flex;gap:12px;margin-top:20px}.chapter-progress>h2,.preview-panel>h2{font-size:22px;margin:32px 0 20px}.chapter-card{scroll-margin-top:20px}.chapter-card header,.chapter-card header>div{display:flex;justify-content:space-between;align-items:center;gap:14px}.chapter-icon{display:grid;place-items:center;width:36px;height:36px;background:#eeebff;border-radius:10px;color:#765edc;font-size:20px}.chapter-card h3{font-size:18px;margin:0 0 7px}.chapter-card small,.chapter-card header>span{font-size:11px;color:#9295aa}.section-tags,.figure-tags{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.section-tags>span,.figure-tags>span{font-size:11px;padding:8px 10px;background:#f5f5fa;border-radius:8px;color:#8a8fa3}.section-tags b{font-size:10px;margin-left:7px;font-weight:400}.section-tags .running{background:#f0ebff;color:#795fdc;animation:pulse 2s infinite}.section-tags .completed{background:#ebf7f2;color:#468873}.section-tags .failed{background:#fff1ec;color:#ba7459}.figure-tags{margin-top:10px}.figure-tags>span{background:none;padding:2px 6px;font-size:10px}.empty-plan{margin-top:42px}.empty-plan>h2{font-size:21px}.empty-plan>div{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.empty-plan article{padding:20px;border:1px solid #e8e6f4;border-radius:14px;background:#ffffff90;scroll-margin-top:20px}.empty-plan small{color:#8c77db}.empty-plan h3{font-size:15px}.empty-plan p,.preview-panel>p{font-size:12px;color:#9194a6;line-height:1.8}.preview-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}.preview-grid figure{margin:0;padding:10px;background:#f7f8fb;border-radius:12px}.preview-grid img{display:block;width:100%;height:260px;object-fit:contain}.preview-grid figcaption{font-size:11px;text-align:center;margin:12px 0;color:#73798b}@keyframes travel{from{transform:translateX(-100%)}to{transform:translateX(500%)}}@keyframes pulse{50%{opacity:.55}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}@media(max-width:1000px){.paper-sidebar{display:none}.paper-main{margin-left:0;padding:25px}.empty-plan>div{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.page-header{align-items:flex-start}.page-header h1{font-size:26px}.title-input{flex-direction:column}.empty-plan>div,.preview-grid{grid-template-columns:1fr}.chapter-card{padding:17px}.chapter-card h3{font-size:15px}.progress-meta{align-items:flex-start;gap:12px;line-height:1.7}}
</style>
